"""Reconcile native rounded quota counters with read-only per-folder IMAP sizes."""
import hashlib,json,pathlib,subprocess,sys
root=pathlib.Path(sys.argv[1]);source=pathlib.Path(sys.argv[2]);scripts=pathlib.Path(sys.argv[3]);p=json.loads((root/'service/durable/operator-state/prepared.json').read_text());project=p['project'];commands=[]
def run(args):
 r=subprocess.run(args,capture_output=True,timeout=120);commands.append({'argv':args,'exit':r.returncode,'stdout_sha256':hashlib.sha256(r.stdout).hexdigest(),'stderr_sha256':hashlib.sha256(r.stderr).hexdigest()});assert r.returncode==0;return r
observed=json.loads(run(['docker','run','--rm','--network',project+'-edge','--user','1000:1000','--mount',f'type=bind,source={source}/keys,target=/keys,readonly','--mount',f'type=bind,source={scripts},target=/lab,readonly','--entrypoint','python3','sha256:36afa984f1187ff7fef17356fa7ead13af9a756681ac4a0c234a58fdc38f47e8','/lab/quota-read-check.py']).stdout);registry=json.loads((root/'service/durable/registry/public/current.json').read_text());checks=[]
for box in observed['boxes']:
 rows=json.loads(run(['docker','exec',project+'-dovecot-1','doveadm','-c','/registry/active.conf','-f','json','quota','get','-u',box['address']]).stdout);rows=[{k.lower():v for k,v in x.items()} for x in rows];storage=next(x for x in rows if x['type']=='STORAGE');messages=next(x for x in rows if x['type']=='MESSAGE');limit=next(x['quota_bytes'] for x in registry['mailboxes'] if x['address']==box['address']);assert int(storage['value'])==(box['virtual_bytes']+1023)//1024 and int(storage['limit'])==(limit+1023)//1024 and int(messages['value'])==box['messages'];assert box['virtual_bytes']<=limit;checks.append({'status':'PASS','imap':box,'native_storage_kib':int(storage['value']),'native_messages':int(messages['value']),'quota_bytes':limit})
result={'status':'PASS_NATIVE_QUOTA_RECONCILIATION','checks':checks,'commands':commands};(root/'quota-reconciliation-result.json').write_text(json.dumps(result,indent=2));print(json.dumps({'status':result['status'],'boxes':len(checks)}))
